CREATE POLICY "read own evidence" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'ari-evidence' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "upload own evidence" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'ari-evidence' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "delete own evidence" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'ari-evidence' AND (storage.foldername(name))[1] = auth.uid()::text);